"use client";

import { useState } from "react";
import { FilterPanel } from "@/components/audio-ui/devices/filter/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useMasterBus } from "@/hooks/use-master-bus";
import { useSpectrum } from "@/hooks/use-spectrum";
import {
  type FilterState,
  filterDevice,
} from "@/components/audio-ui/devices/filter/device";
import { createFilterEngine } from "@/components/audio-ui/devices/filter/engine";

const MASTER_VOLUME = 0.7;
const MIN_HZ = 20;
const MAX_HZ = 20_000;

/**
 * A filter you can plug in: its state, a panel that draws the curve it plays
 * with a handle on the cutoff and an engine that plays it, each its own file
 * and none knowing the others. Play the loop and drag the handle: across for
 * the cutoff, up for the resonance; the spectrum behind is what comes out.
 */
export function BlockFilter() {
  const [state, setState] = useState<FilterState>(() =>
    filterDevice.defaults()
  );
  const master = useMasterBus(MASTER_VOLUME);
  const { analyser } = useDeviceLoop({
    create: createFilterEngine,
    destination: master,
    state,
  });
  const spectrum = useSpectrum(analyser, { maxHz: MAX_HZ, minHz: MIN_HZ });
  return (
    <div className="rounded-2xl h-full w-full min-w-0">
      <FilterPanel onValueChange={setState} spectrum={spectrum} value={state} />
    </div>
  );
}
